import os, json, numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
from PIL import Image

class Controller:
 def __init__(self):
  self.s=rcb_dtb.Session('/app/instance.json');self.m=self.s.model;self.d=mujoco.MjData(self.m); self.d.qpos[:]=self.s.data.qpos
  self.hid=self.m.body('palmleft_hand_C_MC').id;self.hand=np.zeros(22);self.q=rcb_dtb.INIT_Q.copy();self.jp=np.zeros((3,self.m.nv));self.jr=self.jp.copy();self.s.record_start()
 def pose(self):
  return self.s.data.xpos[self.hid].copy(),self.s.data.xmat[self.hid].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  q=self.q.copy() if q is None else q.copy()
  for _ in range(35):
   self.d.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.d)
   e=np.r_[p-self.d.xpos[self.hid],Rot.from_matrix(R@self.d.xmat[self.hid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   mujoco.mj_jacBody(self.m,self.d,self.jp,self.jr,self.hid);J=np.r_[self.jp[:,:7],self.jr[:,:7]]
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]+=dq*np.minimum(1,.15/(np.max(np.abs(dq))+1e-9));q[:7]=np.clip(q[:7],self.s.lower[:7],self.s.upper[:7])
  return q
 def move(self,p,R=None,n=180,hand=None):
  p0,R0=self.pose();R=R0 if R is None else R
  rv=Rot.from_matrix(R@R0.T).as_rotvec();h0=self.hand.copy();h1=h0 if hand is None else np.array(hand)
  for i in range(n):
   t=(i+1)/n;t=t*t*(3-2*t);pt=p0+(p-p0)*t;Rt=Rot.from_rotvec(rv*t).as_matrix()@R0
   self.q=self.ik(pt,Rt);self.hand=h0+(h1-h0)*t;self.q[7:]=self.hand
   self.s.step(self.q)
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.q)
 def snap(self,name):
  print(name,self.s.progress(),'obj',self.s.state()['object_pos'].round(4),'handq',self.s.state()['q'][7:].round(2),flush=True)
  for cam in ['side','front','oblique']:
   Image.fromarray(self.s.render(cam)).save('/app/output/'+name+'_'+cam+'.png')
 def contacts(self):
  for c in self.s.data.contact:
   a,b=c.geom1,c.geom2
   if self.m.geom_bodyid[a]==self.s._obj or self.m.geom_bodyid[b]==self.s._obj:
    print(self.m.geom(a).name,self.m.geom(b).name,'dist',round(c.dist,5),'pos',c.pos.round(4))

if __name__=='__main__':
 c=Controller();s=c.s
 cfg=json.loads(os.environ.get('CFG','{}'));gx=cfg.get('gx',.07);cx=cfg.get('cx',.055);cz=cfg.get('cz',.13)
 R=np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
 c.move(np.array([gx,.057+cz,.75]),R,180);c.hold(30)
 c.move(np.array([gx,.057+cz,.545+cx]),R,180);c.hold(30);c.snap('approach')
 h=np.array(cfg.get('h',[1.5,0,.6,0,.7]+[.65,0,1.5,1]*3+[0,.65,0,1.5,1]))
 c.move(c.pose()[0],R,180,h);c.hold(60);c.snap('close');c.contacts()
 c.move(c.pose()[0]+[0,0,.12],R,240);c.hold(60);c.snap('lift');c.contacts()
 A=s.record_stop();np.save('/app/output/trial.npy',A)
PY
